import{_ as t}from"./chunks/difficulty_easy.76S4H_Nf.js";import{_ as i}from"./chunks/remote_control.ss1psCxn.js";import{_ as a}from"./chunks/altitude_icon.CQEDErje.js";import{_ as l}from"./chunks/altitude_mc.w5-Us6XF.js";import{_ as r,o,c as d,al as _}from"./chunks/framework.7vp1BMOE.js";const P=JSON.parse('{"title":"Режим висоти (мультикоптер)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_mc/altitude.md","filePath":"uk/flight_modes_mc/altitude.md"}'),m={name:"uk/flight_modes_mc/altitude.md"};function s(n,e,c,h,u,f){return o(),d("div",null,[...e[0]||(e[0]=[_('<h1 id="режим-висоти-мультикоптер" tabindex="-1">Режим висоти (мультикоптер) <a class="header-anchor" href="#режим-висоти-мультикоптер" aria-label="Permalink to &quot;Режим висоти (мультикоптер)&quot;">​</a></h1><p><img src="'+t+'" title="Easy to fly" width="30px"> <img src="'+i+'" title="Manual/Remote control required" width="30px"> <img src="'+a+'" title="Altitude required (e.g. Baro, Rangefinder)" width="30px"></p><p><em>Altitude mode</em> is a <em>relatively</em> easy-to-fly RC mode in which roll and pitch sticks control vehicle movement in the left-right and forward-back directions (relative to the &quot;front&quot; of the vehicle), yaw stick controls rate of rotation over the horizontal plane, and throttle controls speed of ascent-descent.</p><p>When the sticks are released/centered the vehicle will level and maintain the current <em>altitude</em>. Якщо апарат рухається в горизонтальній площині, він буде продовжувати рух до тих пір, поки будь-який імпульс не буде погашений опором вітру. Якщо дме вітер, літак буде дрейфувати у напрямку вітру.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><em>Altitude mode</em> is the safest non-GPS manual mode for new fliers. It is just like <a href="./../flight_modes_mc/manual_stabilized">Stabilized</a> mode but additionally locks the vehicle altitude when the sticks are released.</p></div><p>The diagram below shows the mode behaviour visually (for a <a href="./../getting_started/rc_transmitter_receiver#transmitter_modes">mode 2 transmitter</a>).</p><p><img src="'+l+'" alt="Altitude Control MC - Mode2 RC Controller"></p><h2 id="технічнии-підсумок" tabindex="-1">Технічний підсумок <a class="header-anchor" href="#технічнии-підсумок" aria-label="Permalink to &quot;Технічний підсумок&quot;">​</a></h2><p>RC/manual mode like <a href="./../flight_modes_mc/manual_stabilized">Stabilized mode</a> but with <em>altitude stabilization</em> (centred sticks level vehicle and hold it to fixed altitude). Горизонтальне положення транспортного засобу може змінюватися через вплив вітру (або наявного імпульсу).</p><ul><li>Centered sticks: <ul><li>Рівень RPY прикріплюється до транспортного засобу.</li><li>Дросель (~50%) утримує поточну висоту стабільно проти вітру.</li></ul></li><li>Зовнішній центр: <ul><li>Палиці кочення/крену керують кут нахилу у відповідних орієнтаціях, що призводить до відповідного руху ліворуч-праворуч та вперед-назад.</li><li>Ручка дроселя керує швидкістю вгору/вниз з попередньо визначеною максимальною швидкістю (та швидкістю руху в інших осях).</li><li>Палиця крену контролює швидкість кутової ротації вище горизонтальної площини.</li></ul></li><li>Зліт: <ul><li>Після посадки транспортний засіб злетить, якщо важіль керування газом підніметься вище 62.5% від повного діапазону (від низу).</li></ul></li><li>Висота зазвичай вимірюється за допомогою барометра, який може стати неточним в екстремальних погодних умовах. Транспортні засоби, які включають датчик LIDAR/дальнісний датчик, зможуть керувати висотою з більшою надійністю та точністю.</li><li>Потрібен ручний ввід управління (наприклад, за допомогою пульта дистанційного керування, джойстика). <ul><li>Крен, Тангаж: Допомога від автопілота для стабілізації польоту. Положення палиці RC відображає орієнтацію транспортного засобу.</li><li>Газ: Допомога від автопілота для утримання позиції проти вітру.</li><li>Курс: Допомога від автопілота для стабілізації швидкості польоту. Положення палиці RC відображає швидкість обертання транспортного засобу в цій орієнтації.</li></ul></li></ul><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_manual_control"><code>mode_req_manual_control</code></a> — Requires stick input</li></ul><h2 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h2><p>Режим впливає на наступні параметри:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="MPC_Z_VEL_MAX_UP"></a><a href="./../advanced_config/parameter_reference#MPC_Z_VEL_MAX_UP">MPC_Z_VEL_MAX_UP</a></td><td>Максимальна швидкість вертикального підйому. За замовчуванням: 3 м/с.</td></tr><tr><td><a id="MPC_Z_VEL_MAX_DN"></a><a href="./../advanced_config/parameter_reference#MPC_Z_VEL_MAX_DN">MPC_Z_VEL_MAX_DN</a></td><td>Максимальна швидкість вертикального спуску. За замовчуванням: 1 m/s.</td></tr><tr><td><a id="MPC_xxx"></a><code>MPC_XXXX</code></td><td>Більшість параметрів MPC_xxx впливають на поведінку польоту в цьому режимі (принаймні до певної міри). For example, <a href="./../advanced_config/parameter_reference#MPC_THR_HOVER">MPC_THR_HOVER</a> defines the thrust at which a vehicle will hover.</td></tr></tbody></table>',16)])])}const k=r(m,[["render",s]]);export{P as __pageData,k as default};
